from __future__ import annotations

import json
from http import HTTPStatus
from pathlib import Path
from typing import Any, Callable
from urllib.parse import parse_qs


SnapshotLoader = Callable[[], dict[str, Any]]


class MissionControlWebApplication:
    """Loopback-only, read-only web presentation for the operator projection."""

    def __init__(self, snapshot_loader: SnapshotLoader, *, workflow_root: str | Path) -> None:
        self.snapshot_loader = snapshot_loader
        self.workflow_root = Path(workflow_root).resolve()

    def handle(self, environ, start_response):
        if not self._loopback(environ):
            return self._response(start_response, HTTPStatus.FORBIDDEN, b"Local access only", "text/plain; charset=utf-8")
        method = str(environ.get("REQUEST_METHOD", "GET")).upper()
        path = str(environ.get("PATH_INFO", "/"))
        if method != "GET":
            return self._response(start_response, HTTPStatus.METHOD_NOT_ALLOWED, b"Read-only interface", "text/plain; charset=utf-8", [("Allow", "GET")])
        if path in {"/mission-control", "/mission-control/"}:
            return self._response(start_response, HTTPStatus.OK, HTML.encode(), "text/html; charset=utf-8")
        if path == "/mission-control/api":
            body = json.dumps(self.snapshot_loader(), ensure_ascii=False, separators=(",", ":")).encode()
            return self._response(start_response, HTTPStatus.OK, body, "application/json", [("Cache-Control", "no-store")])
        if path == "/mission-control/artifact":
            artifact_id = parse_qs(str(environ.get("QUERY_STRING", ""))).get("artifact_id", [""])[0]
            return self._artifact(artifact_id, start_response)
        return None

    def _artifact(self, artifact_id: str, start_response):
        if not artifact_id or Path(artifact_id).name != artifact_id:
            return self._response(start_response, HTTPStatus.BAD_REQUEST, b"Invalid artefact", "text/plain; charset=utf-8")
        matches = list(self.workflow_root.glob(f"*/artifacts/{artifact_id}.json"))
        if len(matches) != 1:
            return self._response(start_response, HTTPStatus.NOT_FOUND, b"Artefact unavailable", "text/plain; charset=utf-8")
        resolved = matches[0].resolve()
        try:
            resolved.relative_to(self.workflow_root)
        except ValueError:
            return self._response(start_response, HTTPStatus.FORBIDDEN, b"Artefact unavailable", "text/plain; charset=utf-8")
        return self._response(start_response, HTTPStatus.OK, resolved.read_bytes(), "application/json; charset=utf-8", [("Cache-Control", "no-store"), ("Content-Security-Policy", "default-src 'none'")])

    @staticmethod
    def _loopback(environ) -> bool:
        return str(environ.get("REMOTE_ADDR", "")).strip().casefold() in {"127.0.0.1", "::1", "localhost"}

    @staticmethod
    def _response(start_response, status: HTTPStatus, body: bytes, content_type: str, extra=()):
        headers = [("Content-Type", content_type), ("Content-Length", str(len(body))), ("X-Content-Type-Options", "nosniff"), ("X-Frame-Options", "DENY"), ("Referrer-Policy", "no-referrer"), *extra]
        start_response(f"{status.value} {status.phrase}", headers)
        return [body]


HTML = r'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark"><title>Narratiive Mission Control</title>
<style>
:root{--bg:#0b0d0c;--panel:#121513;--panel2:#171b18;--line:#2b312d;--ink:#f1f3ef;--muted:#929b94;--accent:#a8f0c2;--warn:#f0c77a;--bad:#f08f83;--info:#92b9ef;--r:10px}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px/1.45 Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif}button,a{font:inherit}.shell{max-width:1540px;margin:auto;padding:30px 34px 70px}.mast{display:flex;align-items:flex-end;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:22px}.eyebrow,.kicker{text-transform:uppercase;letter-spacing:.16em;font-size:11px;color:var(--muted)}h1{margin:4px 0 0;font-family:Georgia,serif;font-weight:400;font-size:clamp(34px,5vw,66px);line-height:.92;letter-spacing:-.045em}.fresh{display:flex;gap:9px;align-items:center;color:var(--muted)}.dot{width:8px;height:8px;border-radius:50%;background:var(--accent)}.stale .dot{background:var(--bad)}.metrics{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid var(--line)}.metric{padding:26px 18px 22px;border-right:1px solid var(--line)}.metric:first-child{padding-left:0}.metric:last-child{border:0}.metric strong{display:block;font-family:Georgia,serif;font-size:42px;font-weight:400;line-height:1}.metric span{color:var(--muted)}.section{margin-top:36px}.section-head{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}.section h2{font-size:12px;letter-spacing:.16em;text-transform:uppercase;margin:0}.filters{display:flex;gap:6px;flex-wrap:wrap}.filters button{border:1px solid var(--line);background:transparent;color:var(--muted);padding:7px 11px;border-radius:20px;cursor:pointer}.filters button.active{background:var(--ink);border-color:var(--ink);color:var(--bg)}.path{display:grid;grid-template-columns:repeat(7,minmax(145px,1fr));gap:1px;background:var(--line);border:1px solid var(--line);overflow:auto}.lane{background:var(--panel);min-height:250px;padding:14px}.lane h3{margin:0 0 16px;font-size:10px;letter-spacing:.14em;text-transform:uppercase;color:var(--muted)}.opp{width:100%;text-align:left;background:var(--panel2);color:var(--ink);border:1px solid transparent;border-radius:var(--r);padding:13px;margin-bottom:9px;cursor:pointer}.opp:hover,.opp:focus{border-color:var(--accent);outline:none}.tag{display:inline-flex;align-items:center;border:1px solid var(--line);border-radius:20px;padding:2px 7px;font-size:9px;letter-spacing:.12em;margin-bottom:9px}.tag.live{color:var(--accent)}.tag.test{color:var(--warn)}.opp strong{display:block;font-size:14px}.opp small{display:block;color:var(--muted);margin-top:5px}.signal{color:var(--warn)!important}.grid{display:grid;grid-template-columns:1.35fr .65fr;gap:18px}.panel{background:var(--panel);border:1px solid var(--line);border-radius:var(--r);padding:18px}.queue-item,.event,.status-row{padding:12px 0;border-top:1px solid var(--line)}.queue-item:first-child,.event:first-child,.status-row:first-child{border-top:0}.queue-item strong,.event strong{display:block}.queue-item p,.event p{margin:4px 0;color:var(--muted)}.empty{color:var(--muted);padding:22px 0}.systems{display:grid;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));gap:1px;background:var(--line);border:1px solid var(--line)}.system{background:var(--panel);padding:14px}.system b{display:block;margin-bottom:4px}.state{font-size:11px;text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.state.connected,.state.healthy{color:var(--accent)}.state.degraded,.state.blocked{color:var(--bad)}dialog{width:min(1120px,calc(100vw - 32px));max-height:90vh;background:var(--bg);color:var(--ink);border:1px solid var(--line);border-radius:14px;padding:0;overflow:auto}dialog::backdrop{background:#000b}.detail-head{position:sticky;top:0;background:rgba(11,13,12,.95);backdrop-filter:blur(12px);display:flex;justify-content:space-between;align-items:flex-start;padding:22px 24px;border-bottom:1px solid var(--line);z-index:2}.detail-head h2{font:400 34px/1 Georgia,serif;margin:5px 0}.close{background:transparent;border:1px solid var(--line);color:var(--ink);border-radius:50%;width:38px;height:38px;cursor:pointer}.detail-body{padding:24px}.now{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:var(--line);border:1px solid var(--line);margin:18px 0}.now div{background:var(--panel);padding:14px}.now span{display:block;color:var(--muted);font-size:10px;text-transform:uppercase;letter-spacing:.1em;margin-bottom:4px}.blocked{border-left:3px solid var(--bad);padding:14px;background:#281816;margin:14px 0}.journey{display:flex;overflow:auto;padding:18px 0}.step{min-width:130px;position:relative;padding-top:23px;color:var(--muted)}.step:before{content:"○";position:absolute;top:0;font-size:15px}.step:after{content:"";position:absolute;top:8px;left:18px;right:8px;border-top:1px solid var(--line)}.step.complete:before{content:"✓";color:var(--accent)}.step.active:before{content:"●";color:var(--info)}.step.blocked:before{content:"!";color:var(--bad);font-weight:700}.artifact{display:grid;grid-template-columns:1.4fr .5fr .6fr auto;gap:12px;align-items:center;border-top:1px solid var(--line);padding:12px 0}.artifact:first-child{border-top:0}.artifact small{color:var(--muted)}.artifact a{color:var(--accent)}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}
@media(max-width:760px){.shell{padding:20px 16px 50px}.mast{align-items:flex-start;gap:20px}.metrics{grid-template-columns:1fr 1fr}.metric:nth-child(2){border-right:0}.metric:nth-child(-n+2){border-bottom:1px solid var(--line)}.metric:nth-child(3){padding-left:0}.path{display:block;background:none;border:0}.lane{min-height:0;border:1px solid var(--line);margin-bottom:8px}.lane:has(.empty-lane){display:none}.grid{grid-template-columns:1fr}.now{grid-template-columns:1fr}.artifact{grid-template-columns:1fr 1fr}.artifact>*:first-child{grid-column:1/-1}.section-head{align-items:flex-start;gap:12px;flex-direction:column}}
@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}
</style></head>
<body><main class="shell"><header class="mast"><div><div class="eyebrow">Narratiive</div><h1>Mission Control</h1></div><div id="fresh" class="fresh"><span class="dot"></span><span>Connecting</span></div></header>
<section class="metrics" aria-label="Operating summary"><div class="metric"><strong id="m-active">-</strong><span>active opportunities</span></div><div class="metric"><strong id="m-matt">-</strong><span>waiting for Matt</span></div><div class="metric"><strong id="m-blocked">-</strong><span>blocked</span></div><div class="metric"><strong id="m-running">-</strong><span>running autonomously</span></div></section>
<section class="section"><div class="section-head"><h2>The Golden Path</h2><div class="filters" id="filters" aria-label="Portfolio filters"></div></div><div class="path" id="path"></div></section>
<section class="section grid"><div class="panel"><div class="section-head"><h2>Needs You</h2><span class="kicker">Governed human gates only</span></div><div id="queue"></div></div><div class="panel"><div class="section-head"><h2>Attention</h2></div><div id="attention"></div></div></section>
<section class="section grid"><div class="panel"><div class="section-head"><h2>Recent Activity</h2></div><div id="activity"></div></div><div><div class="section-head"><h2>System</h2></div><div class="systems" id="systems"></div></div></section></main>
<dialog id="detail"><div class="detail-head"><div><span id="d-kind" class="tag"></span><h2 id="d-name"></h2><span id="d-stage" class="kicker"></span></div><button class="close" aria-label="Close detail">×</button></div><div class="detail-body" id="detail-body"></div></dialog>
<script>
const lifecycle=[['lead','Lead'],['blueprint_lite','Blueprint Lite'],['discovery','Discovery'],['proposal','Proposal'],['delivery','Delivery'],['commercial','Commercial'],['complete','Complete']];
const filters=[['active','Active'],['needs','Needs Matt'],['blocked','Blocked'],['external','Waiting externally'],['complete','Complete'],['test','Test / Synthetic'],['all','All']];let data=null,current='active';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function show(o){if(current==='all')return !o.synthetic;if(current==='test')return o.synthetic;if(o.synthetic)return false;if(current==='active')return o.lifecycle_stage!=='complete';if(current==='needs')return o.requires_matt;if(current==='blocked')return o.attention_state==='blocked';if(current==='external')return o.attention_state==='waiting_externally';return o.lifecycle_stage==='complete'}
function render(){let s=data.summary;['active','matt','blocked','running'].forEach((x,i)=>document.getElementById('m-'+x).textContent=[s.active_opportunities,s.waiting_for_matt,s.blocked,s.running_autonomously][i]);document.getElementById('filters').innerHTML=filters.map(f=>`<button data-filter="${f[0]}" class="${current===f[0]?'active':''}">${f[1]}</button>`).join('');document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{current=b.dataset.filter;render()});document.getElementById('path').innerHTML=lifecycle.map(([id,label])=>{let os=data.opportunities.filter(o=>o.lifecycle_stage===id&&show(o));return `<section class="lane"><h3>${label} <span>${os.length}</span></h3>${os.length?os.map(card).join(''):'<span class="empty-lane sr">Empty</span>'}</section>`}).join('');document.querySelectorAll('[data-opp]').forEach(b=>b.onclick=()=>openDetail(b.dataset.opp));document.getElementById('queue').innerHTML=data.needs_you.length?data.needs_you.map(q=>`<article class="queue-item"><strong>${esc(q.company)}</strong><p>${esc(q.decision)}</p><small>${esc(q.safe_next_action)}</small></article>`).join(''):'<p class="empty">No genuine human gates are currently recorded.</p>';document.getElementById('attention').innerHTML=data.attention.length?data.attention.map(o=>`<article class="queue-item"><strong>${esc(o.company)}</strong><p>${esc(o.blocker||o.current_activity)}</p><small>${esc(o.attention_state.replaceAll('_',' '))}</small></article>`).join(''):'<p class="empty">No live blockers or failures recorded.</p>';document.getElementById('activity').innerHTML=data.activity.length?data.activity.slice(0,10).map(e=>`<article class="event"><strong>${esc(e.company)}</strong><p>${esc(e.label)}</p><small>${fmt(e.occurred_at)}</small></article>`).join(''):'<p class="empty">No meaningful workflow events recorded.</p>';let cs=data.system.connections;document.getElementById('systems').innerHTML=`<div class="system"><b>Narratiive OS</b><span class="state ${esc(data.system.status)}">${esc(data.system.status)}</span></div>`+cs.map(c=>`<div class="system" title="${esc(c.evidence||'No evidence supplied')}"><b>${esc(c.name)}</b><span class="state ${esc(c.state)}">${esc(c.state.replaceAll('_',' '))}</span></div>`).join('')}
function card(o){return `<button class="opp" data-opp="${esc(o.id)}"><span class="tag ${o.synthetic?'test':'live'}">${o.kind}</span><strong>${esc(o.company)}</strong><small>${esc(o.current_activity)}</small>${o.requires_matt?'<small class="signal">◆ Matt required</small>':''}${o.blocked?`<small class="signal">! ${esc(o.blocker)}</small>`:''}</button>`}
function openDetail(id){let o=data.opportunities.find(x=>x.id===id);if(!o)return;document.getElementById('d-name').textContent=o.company;let k=document.getElementById('d-kind');k.textContent=o.kind;k.className='tag '+(o.synthetic?'test':'live');document.getElementById('d-stage').textContent=o.lifecycle_stage.replaceAll('_',' ')+' / '+o.operational_substate.replaceAll('_',' ');document.getElementById('detail-body').innerHTML=`<h3 class="kicker">Journey</h3><div class="journey">${o.journey.map(x=>`<div class="step ${esc(x.state)}"><span>${esc(x.label)}</span></div>`).join('')}</div>${o.blocked?`<div class="blocked"><strong>BLOCKED</strong><p>${esc(o.blocker)}</p>${o.requires_matt?'<b>MATT REQUIRED</b>':''}</div>`:''}<h3 class="kicker">Now</h3><div class="now"><div><span>Current activity</span>${esc(o.current_activity)}</div><div><span>Owner</span>${esc(o.current_owner)}</div><div><span>Started</span>${fmt(o.started_at)}</div><div><span>Next</span>${esc(o.next_action)}</div><div><span>Blocked</span>${o.blocked?'Yes':'No'}</div><div><span>Matt needed</span>${o.requires_matt?'Yes':'No'}</div></div><h3 class="kicker">Governed artefacts</h3><div>${o.artefacts.length?o.artefacts.map(a=>`<article class="artifact"><div><strong>${esc(a.name)} v${a.version}</strong><small>${esc(a.producer||'Producer not recorded')} · ${fmt(a.created_at)}</small></div><span class="state ${a.quality_status==='passed'?'connected':a.quality_status==='failed'?'degraded':''}">${esc(a.quality_status.replaceAll('_',' '))}</span><small>${esc(a.approval_status.replaceAll('_',' '))}</small>${a.open_url?`<a target="_blank" rel="noreferrer" href="${esc(a.open_url)}">Open</a>`:'<small>Location unavailable</small>'}</article>`).join(''):'<p class="empty">No governed artefacts recorded.</p>'}</div><h3 class="kicker" style="margin-top:28px">Quality and revision history</h3><div>${o.quality_history.length?o.quality_history.map(q=>`<article class="event"><strong>Version ${q.version}: ${q.passed?'Passed quality gate':'Revision required'}</strong><p>${q.failed_criteria.length?esc(q.failed_criteria.join(', ')):'No failed criteria recorded'}</p></article>`).join(''):'<p class="empty">No quality review history recorded.</p>'}</div>`;document.getElementById('detail').showModal();location.hash=encodeURIComponent(id)}
function fmt(v){if(!v)return 'Not recorded';let d=new Date(v);return Number.isNaN(d.valueOf())?esc(v):d.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
document.querySelector('.close').onclick=()=>{document.getElementById('detail').close();history.replaceState(null,'',location.pathname)};document.getElementById('detail').onclick=e=>{if(e.target.id==='detail')document.querySelector('.close').click()};
async function load(){try{let r=await fetch('/mission-control/api',{cache:'no-store'});if(!r.ok)throw Error('HTTP '+r.status);data=await r.json();render();let age=(Date.now()-new Date(data.generated_at))/1000,f=document.getElementById('fresh');f.classList.toggle('stale',age>data.stale_after_seconds);f.querySelector('span:last-child').textContent='Last updated '+fmt(data.generated_at);if(location.hash){let id=decodeURIComponent(location.hash.slice(1));if(data.opportunities.some(o=>o.id===id))openDetail(id)}}catch(e){let f=document.getElementById('fresh');f.classList.add('stale');f.querySelector('span:last-child').textContent='State unavailable'}}load();setInterval(load,10000);
</script></body></html>'''
